import './realtor-runtime-20261019.mjs';import fs from 'node:fs/promises';const{db}=await import('./reply-runtime-20261015.mjs');
const dir='artifacts/faq-30days-20261019';await fs.mkdir(dir,{recursive:true});const end=new Date().toISOString(),start=new Date(Date.parse(end)-30*86400000).toISOString();const manifest={start,end,tables:{},limits:['CRM records only; provider mailboxes and audio/attachments not independently re-opened.']};
for(const table of ['market_touches','sms_messages','call_recordings']){const rows=[];for(let offset=0;;offset+=1000){const p=await db(table,{and:`(created_at.gte.${start},created_at.lte.${end})`,order:'created_at.asc,id.asc',offset:String(offset),limit:'1000'});rows.push(...p);if(p.length<1000)break;}await fs.writeFile(dir+'/'+table+'.json',JSON.stringify(rows));manifest.tables[table]={rows:rows.length};console.log(table+' '+rows.length);}
const touches=JSON.parse(await fs.readFile(dir+'/market_touches.json'));const ids=[...new Set(touches.filter(t=>t.direction==='inbound').map(t=>t.contact_id).filter(Boolean))],contacts=[];for(let i=0;i<ids.length;i+=100)contacts.push(...await db('market_contacts',{id:'in.('+ids.slice(i,i+100).join(',')+')'}));await fs.writeFile(dir+'/contacts.json',JSON.stringify(contacts));manifest.contacts=contacts.length;manifest.tables.market_touches.inbound=touches.filter(t=>t.direction==='inbound').length;await fs.writeFile(dir+'/manifest.json',JSON.stringify(manifest,null,2));console.log(JSON.stringify(manifest));
